  VERIFIED:   "invariant",  // passed a deterministic gate
  OBSERVED:   "observed",   // tool output, real but unchecked
  HYPOTHESIS: "volatile",   // model claim / plan / guess
  RECOVERY:   "volatile",   // model apology/recovery text — compaction fodder
